```tsx
function MonitoringPage({setTheme}: {setTheme: (t: Theme) => void}) {
  const themeValue = useThemeValue();
  const dark = themeValue === 'dark' || themeValue === 'dark-hc';
  const [stats, setStats] = useState<CpuStats | null>(null);
