export const STEP_MS = 1000;
export const WINDOW_MS = 24 * 60 * 60 * 1000;
export const POINTS_PER_WINDOW = WINDOW_MS / STEP_MS; // 86_400

/** Максимум точек, которые догоняем после «сна» вкладки; дальше — полная перегенерация окна. */
export const MAX_CATCH_UP_POINTS = 3600;

export interface CpuWindow {
  timeline: number[]; // ms, выровнены по STEP_MS
  values: number[]; // % загрузки 0..100
}

export function alignTime(ts: number): number {
  return Math.floor(ts / STEP_MS) * STEP_MS;
}
```

Random walk with mean reversion + daily cycle + spikes. Seeded PRNG mulberry32 for deterministic history.

```ts
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
```

Daily baseline: day/night cycle. Timezone: use local hours.

```ts
function baseline(t: number): number {
  const hours = new Date(t).getHours() + new Date(t).getMinutes() / 60;
  // ночной минимум ~18%, дневной пик ~45%
  const day = 31.5 + 13.5 * Math.sin(((hours - 9) / 24) * Math.PI * 2);
  return day;
}
```

