```ts
export function createCpuSampler(seed = 42) {
  const rand = mulberry32(seed);
  let level = 32;
  return (t: number): number => {
    const base = baseline(t);
    // mean reversion + jitter
    level += (base - level) * 0.02 + (rand() - 0.5) * 6;
    // редкие всплески
    if (rand() < 0.002) level += 25 + rand() * 30;
    // редкие провалы
    if (rand() < 0.001) level -= 15 + rand() * 10;
    level = Math.min(98, Math.max(2, level));
    return level;
  };
}
```

