/** Сгенерировать недостающие точки от lastT до now (включительно). Возвращает null если нечего добавлять. */
export function extendWindow(w: CpuWindow, sampler, now = Date.now()): {timeline: number[]; values: number[]} | null {
  const end = alignTime(now);
  const lastT = w.timeline[w.timeline.length - 1];
  const gap = Math.round((end - lastT) / STEP_MS);
  if (gap <= 0) return null;
  const count = Math.min(gap, MAX_CATCH_UP_POINTS);
  const timeline: number[] = new Array(count);
  const values: number[] = new Array(count);
  const startT = end - (count - 1) * STEP_MS;
  let prev = w.values[w.values.length - 1];
  for (let i = 0; i < count; i++) {
    timeline[i] = startT + i * STEP_MS;
    values[i] = sampler(timeline[i]);
  }
  // обновляем локальное окно
  w.timeline.push(...timeline); w.values.push(...values);
  const overflow = w.timeline.length - POINTS_PER_WINDOW;
  if (overflow > 0) { w.timeline.splice(0, overflow); w.values.splice(0, overflow); }
  return {timeline, values};
}
