body {
    margin: 0;
}

.page {
    box-sizing: border-box;
    min-height: 100vh;
    max-width: 1200px;
    margin: 0 auto;
    padding: 24px;
    display: flex;
    flex-direction: column;
    gap: 20px;
}

.page__header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 16px;
    flex-wrap: wrap;
}

.page__header h1 {
    margin: 0;
}

.stats {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 12px;
}

.stat {
    padding: 16px;
    border-radius: 12px;
    background: var(--g-color-base-float);
}

.stat__value {
    margin-top: 4px;
}

.chart-card {
    padding: 16px 16px 8px;
}

.chart-card__header {
    display: flex;
    align-items: baseline;
    gap: 12px;
    flex-wrap: wrap;
    margin-bottom: 8px;
}

.chart-card__header h2 {
    margin: 0;
}

/* Контейнер графика: ширина — по карточке, высота фиксированная,
   дальше yagr сам следит за размерами (adaptive + ResizeObserver). */
.cpu-chart {
    width: 100%;
    min-width: 0;
    height: 380px;
}

.table-view summary {
    cursor: pointer;
    color: var(--g-color-text-secondary);
}

.table-view table {
    margin-top: 12px;
    border-collapse: collapse;
    min-width: 320px;
    font-variant-numeric: tabular-nums;
}

.table-view th,
.table-view td {
    text-align: left;
    padding: 6px 24px 6px 0;
    border-bottom: 1px solid var(--g-color-line-generic);
    color: var(--g-color-text-primary);
    font-size: var(--g-text-body-2-font-size);
}

.table-view th {
    color: var(--g-color-text-secondary);
    font-weight: normal;
}

