args.content:
import {chromium} from 'playwright-core';

const URL = 'http://localhost:5200/';
const OUT = '/tmp/pwtest';

const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1280, height: 950}});

const errors = [];
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
page.on('pageerror', (e) => errors.push(String(e)));

await page.goto(URL, {waitUntil: 'networkidle'});
await page.waitForSelector('.cpu-chart canvas', {timeout: 15000});
await page.waitForTimeout(2500); // пара секунд реального времени

await page.screenshot({path: `${OUT}/light.png`, fullPage: true});

// Переключить тему
await page.getByRole('button', {name: /тёмная тема|светлая тема/i}).click();
await page.waitForTimeout(800);
await page.screenshot({path: `${OUT}/dark.png`, fullPage: true});

// Проверка адаптивности: сузить окно
await page.setViewportSize({width: 700, height: 950});
await page.waitForTimeout(600);
await page.screenshot({path: `${OUT}/dark-narrow.png`, fullPage: true});

// Открыть табличное представление
await page.locator('.table-view summary').click();
await page.waitForTimeout(300);
await page.screenshot({path: `${OUT}/table.png`, fullPage: true});

console.log('console errors:', errors.length ? errors : 'none');
await browser.close();

