args.command:
cd /tmp/pwtest && cat > interact.mjs <<'EOF'
import {chromium} from 'playwright-core';
const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1280, height: 950}});
await page.route(/fonts\.googleapis\.com|fonts\.gstatic\.com/, r => r.abort());
await page.goto('http://127.0.0.1:5300/', {waitUntil: 'load', timeout: 30000});
await page.waitForSelector('.cpu-chart canvas', {timeout: 15000});
await page.waitForTimeout(1500);

const box = await page.locator('.cpu-chart canvas').boundingBox();
// Ховер — тултип
await page.mouse.move(box.x + box.width * 0.6, box.y + box.height * 0.5);
await page.waitForTimeout(700);
const tooltip = await page.locator('.yagr-tooltip').first().textContent().catch(() => null);
console.log('tooltip:', tooltip ? tooltip.replace(/\s+/g, ' ').slice(0, 120) : 'NOT FOUND');
await page.screenshot({path: '/tmp/pwtest/hover.png', clip: {x: box.x - 120, y: box.y - 60, width: box.width + 240, height: box.height + 160}});

// Драг-зум
const before = await page.evaluate(() => document.querySelector('.cpu-chart canvas').width);
await page.mouse.move(box.x + box.width * 0.3, box.y + box.height * 0.5);
await page.mouse.down();
await page.mouse.move(box.x + box.width * 0.5, box.y + box.height * 0.5, {steps: 10});
await page.mouse.up();
await page.waitForTimeout(600);
await page.screenshot({path: '/tmp/pwtest/zoomed.png', clip: {x: box.x - 120, y: box.y - 60, width: box.width + 240, height: box.height + 120}});
console.log('zoom done, canvas width stable:', before > 0);

// Двойной клик — сброс
await page.mouse.dblclick(box.x + box.width * 0.5, box.y + box.height * 0.5);
await page.waitForTimeout(600);
await page.screenshot({path: '/tmp/pwtest/reset.png', clip: {x: box.x - 120, y: box.y - 60, width: box.width + 240, height: box.height + 120}});
await browser.close();
console.log('interactions ok');
EOF
