import http from 'node:http';
import {readFile} from 'node:fs/promises';
import {join, extname} from 'node:path';
const root = '/home/sandbox/workspace/dist';
const mime = {'.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.svg': 'image/svg+xml', '.png': 'image/png', '.woff2': 'font/woff2', '.woff': 'font/woff'};
http.createServer(async (req, res) => {
  try {
    let p = req.url.split('?')[0];
    if (p === '/') p = '/index.html';
    const data = await readFile(join(root, p));
    res.writeHead(200, {'content-type': mime[extname(p)] || 'application/octet-stream'});
    res.end(data);
  } catch {
    res.writeHead(404); res.end('nf');
  }
}).listen(5300, '127.0.0.1', () => console.log('serving on 127.0.0.1:5300'));
